.edublink-course-ajax-search-result-inner ul li a, .edublink-course-ajax-search-result-inner ul li { 
    color: #ffffff;
    font-family: "Libre Franklin", Sans-serif;
}

#video-popup-home .edublink-video-popup-icon {

    display: flex;
    flex-direction: row;
    align-items: center;

}

#video-popup-home .edublink-video-popup-icon svg {
    margin-left: 10px;
    height: 60px;
    width: 100%;
}

#seccion-faq .eb-accordion-item {
    background-color: rgb(101 101 101 / 0%);
    border-top: 1px solid #F2F2F2;
  border-radius: 0px;
    margin-bottom: 0px;
}
#seccion-faq .eb-accordion.border-b-1 .eb-accordion-item.active-item .eb-accordion-content {
    box-shadow: none;
}

#seccion-faq .eb-accordion-item:last-child {
  border-bottom: 1px solid #F2F2F2; 
}
#seccion-faq .eb-accordion.header-transparent-bg .eb-accordion-item .eb-accordion-header  {
      border-radius: 0px;
          border: none;
        padding: 33px 45px 33px 30px;
}
#seccion-faq .eb-accordion-item .eb-accordion-header, #seccion-faq .eb-accordion-item .eb-accordion-body {
    color: #F2F2F2;
     font-family: 'Libre Franklin';
}

#seccion-faq .eb-accordion-header.default-active.active, #seccion-faq .eb-accordion-item .eb-accordion-body, #seccion-faq .eb-accordion.header-transparent-bg .eb-accordion-item .eb-accordion-header.active {
        background-color: rgba(101, 101, 101, 0.0);
        font-family: 'Libre Franklin';
}

#seccion-faq .eb-accordion-header.default-active.active:before, #seccion-faq .eb-accordion-header:before {
    color: #F2F2F2;
}
